def _derive(pw):
    return hashlib.pbkdf2_hmac("sha256", pw.encode(), _S, _I, 32)

def _ok(key):
    return hashlib.sha256(b"dhc-verify|" + key).hexdigest() == _V

def _xor(data, key):
    out = bytearray(len(data)); i = 0; ctr = 0
    while i < len(data):
        ks = hashlib.sha256(key + ctr.to_bytes(8, "big")).digest()
        for j in range(len(ks)):
            if i + j >= len(data): break
            out[i + j] = data[i + j] ^ ks[j]
        i += len(ks); ctr += 1
    return bytes(out)

def _unlock():
    env = os.environ.get("DHC_PW")
    if env:
        k = _derive(env)
        if _ok(k):
            return env, k
        sys.stderr.write("DHC_PW is set but the password is wrong.\n"); sys.exit(1)
    if not sys.stdin.isatty():
        sys.stderr.write("Password required. Run it in a terminal, or set DHC_PW.\n"); sys.exit(1)
    for _ in range(3):
        try:
            pw = getpass.getpass("Enter password to run the health check: ")
        except (EOFError, KeyboardInterrupt):
            sys.exit(1)
        k = _derive(pw)
        if _ok(k):
            return pw, k
        print("Wrong password.")
    sys.stderr.write("Access denied.\n"); sys.exit(1)

def _main():
    # Elevate first so the password is asked only once (as root).
    if hasattr(os, "geteuid") and os.geteuid() != 0:
        os.execvp("sudo", ["sudo", sys.executable, os.path.abspath(sys.argv[0])] + sys.argv[1:])
    pw, key = _unlock()
    os.environ["DHC_PW"] = pw            # so a tmux/self relaunch does not re-ask
    code = _xor(base64.b85decode("".join(_B.split())), key).decode("utf-8")
    g = {"__name__": "__main__", "__file__": os.path.abspath(sys.argv[0])}
    exec(compile(code, "disk_health_check.py", "exec"), g)

if __name__ == "__main__":
    _main()
